public class ZipArchiveEntry_isUnixSymlink_TriageGen1Test {

    /**
     * Test case where the Unix mode bitmask results in exactly the LINK_FLAG.
     * This tests the boundary condition (<= UnixStat.LINK_FLAG).
     */
    @Test
    public void testIsUnixSymlink_WithLinkFlag() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link");
        // Set mode to exactly the LINK_FLAG
        // (LINK_FLAG & FILE_TYPE_FLAG) should be <= LINK_FLAG
        entry.setUnixMode(UnixStat.LINK_FLAG);
        assertTrue("Should return true when mode is exactly LINK_FLAG", entry.isUnixSymlink());
    }








